<script setup>
import InputError from '@/Components/InputError.vue';import{useForm}from'@inertiajs/vue3';
const props=defineProps({profile:Object});const flags=['allow_create','allow_edit','allow_delete','allow_export','allow_email','allow_sms','allow_payment','allow_configuration','allow_user_management'];const form=useForm({name:props.profile.name,public_demo_url:props.profile.public_demo_url||'',is_active:props.profile.is_active,requires_access_token:props.profile.requires_access_token,...Object.fromEntries(flags.map(k=>[k,props.profile[k]])),protected_roles:props.profile.protected_roles||[],protected_accounts:props.profile.protected_accounts||[],configuration:props.profile.configuration||{},reset_enabled:props.profile.reset_enabled,reset_schedule:props.profile.reset_schedule||'',reset_instructions:props.profile.reset_instructions||'',next_reset_at:props.profile.next_reset_at?.slice(0,16)||''});const save=()=>form.put(route('admin.demo-mode.update',props.profile.uuid),{preserveScroll:true});
</script>
<template><form class="space-y-5" @submit.prevent="save"><div class="form-grid"><label>Name<input v-model="form.name" required/></label><label>Public demo URL<input v-model="form.public_demo_url" type="url"/></label></div><div class="flex flex-wrap gap-5"><label class="flex items-center gap-2"><input v-model="form.is_active" type="checkbox"/> Configuration active</label><label class="flex items-center gap-2"><input v-model="form.requires_access_token" type="checkbox"/> Require access token</label></div><fieldset><legend class="mb-3 font-bold">Product-enforced capabilities</legend><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><label v-for="flag in flags" :key="flag" class="flex items-center gap-2 rounded-lg border p-3"><input v-model="form[flag]" type="checkbox"/><span>{{ flag.replace('allow_','').replaceAll('_',' ') }}</span></label></div></fieldset><div class="form-grid"><label>Protected roles<input :value="form.protected_roles.join(', ')" @input="form.protected_roles=$event.target.value.split(',').map(v=>v.trim()).filter(Boolean)"/></label><label>Protected accounts<input :value="form.protected_accounts.join(', ')" @input="form.protected_accounts=$event.target.value.split(',').map(v=>v.trim()).filter(Boolean)"/></label></div><fieldset class="rounded-xl border p-4"><legend class="px-2 font-bold">Product-owned reset instructions</legend><label class="flex items-center gap-2"><input v-model="form.reset_enabled" type="checkbox"/> Enable scheduled reset instruction</label><div class="mt-4 form-grid"><label>Cron schedule<input v-model="form.reset_schedule" placeholder="0 */6 * * *"/></label><label>Next expected reset<input v-model="form.next_reset_at" type="datetime-local"/></label></div><label>Instructions<textarea v-model="form.reset_instructions" rows="4"/></label><p class="mt-2 text-sm text-slate-500">KernelBridge publishes this instruction only. The product owns and executes its reset locally.</p></fieldset><InputError :message="form.errors.reset_instructions"/><button class="form-button" :disabled="form.processing">Publish configuration</button></form></template>
